fts5.h1_f:
CREATE VIRTUAL TABLE messaggi_fts USING fts5(
  contenuto, -- colonna tokenizzata
  room_id UNINDEXED,
  tokenize = 'unicode61 rimuovi_diacritici 2'
);
query: SELECT rowid FROM messaggi_fts WHERE contenuto MATCH 'foo'

